import { combineSystemPrompts } from './prompts';
import { discountPrompt } from './prompts/discount';
import { logPromptInfo, estimateTokens } from '@/utils/promptLogger';

export interface PromptTemplate {
  id: string;
  title: string;
  content: string;
  description?: string;
}

// 가격 검증 규칙을 포함한 공통 프롬프트
const PRICE_VALIDATION_RULE = `
**가격 계산 및 검증 규칙 (모든 견적서 생성 시 필수 준수):**

1. **가격 계산 순서:**
   - 모든 개별 기능의 'amount' 값을 숫자로 변환하여 합산
   - 합산된 금액을 'total.amount'에 정확히 반영
   - 'total.totalConvertedDisplay'는 'total.amount'와 사용자의 국가 코드 및 환율 정보를 바탕으로 정확히 계산

2. **가격 일관성 검증 (필수):**
   - 견적서 생성 후 반드시 다음을 확인하세요:
     - 모든 개별 기능 'amount'의 합계 = 'total.amount'
     - 'total.totalConvertedDisplay'가 올바른 환율로 계산되었는가?
   - 만약 불일치가 발견되면 즉시 수정하여 일치시켜야 합니다.

3. **최종 검증 체크리스트:**
   a. 모든 개별 기능의 'amount' 합계가 'total.amount'와 정확히 일치하는가?
   b. 'total.totalConvertedDisplay'가 올바른 통화와 환율로 표시되었는가?
   c. 모든 가격이 올바른 형식으로 표시되었는가?
   d. 프로젝트명과 설명이 명확하고 일관성 있는가?

4. **가격 불일치 시 즉시 수정:**
   - 검증 과정에서 가격 불일치가 발견되면, 개별 기능 가격을 다시 계산하고 'total.amount'를 정확한 합계로 업데이트
   - 수정된 견적서를 다시 검증하여 완벽한 일치를 보장
`;

export const promptTemplates: PromptTemplate[] = [
  {
    id: 'default',
    title: '기본 시스템 프롬프트',
    content: `${combineSystemPrompts()}\n\n${PRICE_VALIDATION_RULE}`,
    description: '기본 AI 시스템 프롬프트와 가격 검증 규칙이 포함되어 있습니다.'
  },
  {
    id: 'discount',
    title: '할인 및 프로모션 처리',
    content: `${discountPrompt}\n\n${PRICE_VALIDATION_RULE}`,
    description: '할인 및 프로모션 관련 처리와 가격 검증 규칙이 포함되어 있습니다.'
  },
  // 여기에 추가 프롬프트 템플릿을 작성하세요
];

export const getPromptTemplate = (id: string): PromptTemplate | undefined => {
  return promptTemplates.find(template => template.id === id);
};

export const combinePrompts = (templateId: string, userInput: string): string => {
  const template = getPromptTemplate(templateId);
  if (!template) return userInput;

  const combinedPrompt = `${template.content}\n\n사용자 입력: ${userInput}`;

  // 토큰 수 추정
  const promptTokens = estimateTokens(combinedPrompt);
  // 응답 토큰은 입력의 약 1.5배로 가정
  const completionTokens = Math.ceil(promptTokens * 1.5);

  // 로그 출력
  logPromptInfo({
    templateId,
    userInput,
    combinedPrompt,
    tokenInfo: {
      promptTokens,
      completionTokens,
      totalTokens: promptTokens + completionTokens
    }
  });

  return combinedPrompt;
};
